/* 0077_a_listing_with_no_niche_has_no_niche.sql, flattened for the Supabase SQL editor. Generated by scripts/flatten-migration.mjs - do not edit this file, edit the migration and run the script again. One statement per line, no line comments, nothing to lose to a newline. The commentary lives in the migration itself. */
create or replace view public.marketplace_listings with (security_invoker = true) as select w.id, w.slug, w.domain, coalesce(nullif(btrim(w.title), ''), w.domain) as title, coalesce(w.description, '') as description, pc.slug as niche, coalesce(sec.slugs, '{}'::text[]) as secondary_niches, case when w.country_source = 'default' then null else w.country_code end as country, coalesce(w.language_code, 'en') as language, w.domain_rating, w.organic_traffic, w.referring_domains, w.organic_keywords, w.verified, w.completed_orders, w.created_at, w.link_attribute, coalesce(w.accepted_niches, '{}'::text[]) as accepted_niches, w.status, coalesce(w.audience_split, '[]'::jsonb) as audience_split from public.websites w left join public.categories pc on pc.id = w.primary_category_id left join lateral ( select array_agg(distinct c.slug) as slugs from public.website_categories wc join public.categories c on c.id = wc.category_id where wc.website_id = w.id and c.slug is distinct from pc.slug ) sec on true;
comment on view public.marketplace_listings is 'The marketplace as the app sees it, not as the columns store it: country hidden when its source is "default", niche null when nobody has set one, title falling back to the domain. security_invoker, so the websites policy decides what it returns.';
create or replace function public.marketplace_facets(p_topic text default null) returns table (kind text, value text, count bigint) language sql stable set search_path = public as $$ with topic as ( select nullif(nullif(btrim(coalesce(p_topic, '')), ''), 'general') as slug ), offered as ( select m.* from public.marketplace_listings m cross join topic t where m.status = 'active' and (t.slug is null or m.accepted_niches @> array[t.slug]) ) select 'niche'::text, m.niche, count(*) from public.marketplace_listings m where m.status = 'active' and m.niche is not null group by m.niche union all select 'language'::text, m.language, count(*) from public.marketplace_listings m where m.status = 'active' group by m.language union all select 'country'::text, o.country, count(*) from offered o where o.country is not null group by o.country union all select 'country-unstated'::text, ''::text, count(*) from offered o where o.country is null; $$;
comment on function public.marketplace_facets(text) is 'Niche, language and country counts for the marketplace sidebar. Niche and language over every active listing, country over the topic being bought for. A listing with no primary category is in no niche count, because no niche filter returns it.';
create or replace function public.marketplace_niche_preview( p_niche text, p_limit integer default 6 ) returns table (id uuid, total bigint, countries bigint) language sql stable set search_path = public as $$ with matched as ( select w.id, w.domain_rating, case when w.country_source = 'default' then null else w.country_code end as country from public.websites w left join public.categories pc on pc.id = w.primary_category_id where w.status = 'active' and ( pc.slug = p_niche or exists ( select 1 from public.website_categories wc join public.categories c on c.id = wc.category_id where wc.website_id = w.id and c.slug = p_niche ) ) ), counted as ( select count(*) as total, count(distinct country) filter (where country is not null) as countries from matched ), ordered as ( select m.id, row_number() over (order by m.domain_rating desc, m.id asc) - 1 as position from matched m ) select ordered.id, counted.total, counted.countries from ordered cross join counted where ordered.position % greatest(1, counted.total / greatest(coalesce(p_limit, 6), 1)) = 0 order by ordered.position limit greatest(1, least(coalesce(p_limit, 6), 24)); $$;
comment on function public.marketplace_niche_preview(text, integer) is 'A spread of a niche''s listings plus its totals, in one query. A listing with no primary category belongs to no niche and appears in none of them.';
create or replace function public.marketplace_search( p_search text default null, p_niches text[] default null, p_countries text[] default null, p_audience_country text default null, p_audience_share_min integer default null, p_audience_traffic_min integer default null, p_languages text[] default null, p_link_types text[] default null, p_link_attribute text default null, p_dr_min integer default null, p_dr_max integer default null, p_traffic_min integer default null, p_traffic_max integer default null, p_rd_min integer default null, p_rd_max integer default null, p_price_min integer default null, p_price_max integer default null, p_max_turnaround integer default null, p_verified boolean default false, p_topic text default null, p_sort text default 'relevance', p_limit integer default 25, p_offset integer default 0 ) returns table (id uuid, total bigint) language sql stable set search_path = public as $$ with topic as ( select nullif(nullif(btrim(coalesce(p_topic, '')), ''), 'general') as slug ), matched as ( select m.id, pl.headline_price, pl.headline_turnaround, m.domain_rating, m.organic_traffic, m.referring_domains, m.organic_keywords, m.created_at, case when coalesce(btrim(p_search), '') = '' then 0 else (case when position(lower(btrim(p_search)) in lower(m.domain)) = 1 then 100 else 0 end) + (case when position(lower(btrim(p_search)) in lower(m.domain)) > 0 then 60 else 0 end) + (case when position(lower(btrim(p_search)) in lower(m.title)) > 0 then 30 else 0 end) + (case when position(lower(btrim(p_search)) in coalesce(m.niche, '')) > 0 then 20 else 0 end) + (case when position(lower(btrim(p_search)) in lower(m.description)) > 0 then 10 else 0 end) end as relevance, m.domain_rating * 1000 + m.completed_orders as quality from public.marketplace_listings m cross join topic t cross join lateral public.marketplace_placements(m.id, t.slug, p_link_types, p_price_min, p_price_max) pl where m.status = 'active' and ( coalesce(btrim(p_search), '') = '' or ( select bool_and( position(part in lower( m.domain || ' ' || m.title || ' ' || m.description || ' ' || coalesce(m.niche, '') || ' ' || array_to_string(m.secondary_niches, ' ') )) > 0 ) from unnest( string_to_array(regexp_replace(lower(btrim(p_search)), '\s+', ' ', 'g'), ' ') ) as part where part <> '' ) ) and (p_niches is null or cardinality(p_niches) = 0 or (m.niche is not null and m.niche = any (p_niches)) or m.secondary_niches && p_niches) and (p_countries is null or cardinality(p_countries) = 0 or (m.country is not null and m.country = any (p_countries))) and (p_languages is null or cardinality(p_languages) = 0 or m.language = any (p_languages)) and ( coalesce(btrim(p_audience_country), '') = '' or exists ( select 1 from jsonb_array_elements(m.audience_split) as slice where upper(slice ->> 'country') = upper(btrim(p_audience_country)) and (p_audience_share_min is null or coalesce((slice ->> 'share')::numeric, 0) >= p_audience_share_min) and (p_audience_traffic_min is null or coalesce((slice ->> 'traffic')::numeric, 0) >= p_audience_traffic_min) ) ) and (p_link_attribute is null or m.link_attribute::text = p_link_attribute) and (p_dr_min is null or m.domain_rating >= p_dr_min) and (p_dr_max is null or m.domain_rating <= p_dr_max) and (p_traffic_min is null or m.organic_traffic >= p_traffic_min) and (p_traffic_max is null or m.organic_traffic <= p_traffic_max) and (p_rd_min is null or m.referring_domains >= p_rd_min) and (p_rd_max is null or m.referring_domains <= p_rd_max) and (not coalesce(p_verified, false) or m.verified) and (t.slug is null or m.accepted_niches @> array[t.slug]) and (p_link_types is null or cardinality(p_link_types) = 0 or pl.has_link_type) and ((p_price_min is null and p_price_max is null) or pl.price_in_window) and (p_max_turnaround is null or (pl.fastest_max_turnaround is not null and pl.fastest_max_turnaround <= p_max_turnaround)) ) select matched.id, count(*) over () as total from matched order by case when p_sort = 'kw-asc' then matched.organic_keywords end asc nulls last, case when p_sort = 'kw-desc' then matched.organic_keywords end desc nulls last, case when p_sort = 'price-asc' then matched.headline_price end asc, case when p_sort = 'price-desc' then matched.headline_price end desc, case when p_sort = 'dr-asc' then matched.domain_rating end asc, case when p_sort = 'dr-desc' then matched.domain_rating end desc, case when p_sort = 'traffic-asc' then matched.organic_traffic end asc, case when p_sort = 'traffic-desc' then matched.organic_traffic end desc, case when p_sort = 'rd-asc' then matched.referring_domains end asc, case when p_sort = 'rd-desc' then matched.referring_domains end desc, case when p_sort = 'turnaround-asc' then matched.headline_turnaround end asc, case when p_sort = 'turnaround-desc' then matched.headline_turnaround end desc, case when p_sort = 'newest' then matched.created_at end desc, case when p_sort = 'relevance' or p_sort is null then matched.relevance end desc, case when p_sort = 'relevance' or p_sort is null then matched.quality end desc, matched.domain_rating desc, matched.id asc limit greatest(1, least(coalesce(p_limit, 25), 100)) offset greatest(0, coalesce(p_offset, 0)); $$;
comment on function public.marketplace_search( text, text[], text[], text, integer, integer, text[], text[], text, integer, integer, integer, integer, integer, integer, integer, integer, integer, boolean, text, text, integer, integer ) is 'One page of the marketplace. Prices each candidate listing through the index on services(website_id) rather than pricing the whole marketplace first, and can narrow by where a publisher''s readers are as well as where the publisher is. A listing with no primary category matches no niche filter and still matches everything else.';
